#!/usr/bin/env bash
set -euo pipefail

ROOT=$(bd create --silent --type epic --title "MVP игры \"Компьютерщик\"" --description "Корневой эпик MVP браузерной игры по текущему документу требований.")
CORE=$(bd create --silent --type epic --parent "$ROOT" --title "Игровое ядро и время" --description "Общие системы времени, таймеров, состояния и сохранения.")
HERO=$(bd create --silent --type epic --parent "$ROOT" --title "Герой, здоровье и жизненный цикл" --description "Характеристики героя, здоровье, голод, старение, имущество и смерть.")
CAREER=$(bd create --silent --type epic --parent "$ROOT" --title "Специальности, обучение и карьера" --description "Профессии, уровни квалификации, обучение и карьерные переходы.")
ORDERS=$(bd create --silent --type epic --parent "$ROOT" --title "ПК и система заказов" --description "Конфигурация ПК, разовые задачи, уровни сложности, награды и провалы.")
SOCIAL=$(bd create --silent --type epic --parent "$ROOT" --title "Хобби, друзья, семья и питомцы" --description "Прогулки, приключения, друзья, отношения, дети и питомцы.")
UI=$(bd create --silent --type epic --parent "$ROOT" --title "Страницы и интерфейс MVP" --description "Маршруты приложения и экраны игры.")
CONTENT=$(bd create --silent --type epic --parent "$ROOT" --title "Контент и балансировка" --description "Начальные справочники, деревья ролей, книги, задания и формулы баланса.")

bd create --silent --type task --parent "$CORE" --title "Описать модель игрового времени" --description "Зафиксировать преобразование 1 минута = 1 месяц и 10 минут = 1 год, а также список систем, на которые влияет время."
bd create --silent --type task --parent "$CORE" --title "Реализовать универсальную систему таймеров" --description "Нужна единая модель таймеров для работы, учебы, прогулок, лечения и заказов."
bd create --silent --type task --parent "$CORE" --title "Определить правила фонового прогресса" --description "Система должна корректно завершать таймеры и пересчитывать прогресс после перезахода в игру."
bd create --silent --type task --parent "$CORE" --title "Спроектировать единое игровое состояние" --description "Нужно определить структуру состояния игрока, активностей, контента и производных показателей."
bd create --silent --type task --parent "$CORE" --title "Добавить локальное сохранение прогресса" --description "MVP должен сохранять состояние игры локально и восстанавливать его после перезагрузки страницы."

bd create --silent --type task --parent "$HERO" --title "Описать базовые характеристики героя" --description "Возраст, деньги, капитал, здоровье, голод, вес, спорт, семья, питомцы и имущество."
bd create --silent --type task --parent "$HERO" --title "Определить механику голода и смерти" --description "Сильный голод должен приводить к риску смерти, с понятными порогами и последствиями."
bd create --silent --type task --parent "$HERO" --title "Определить механику здоровья, веса и спорта" --description "Нужно задать влияние спорта на вес и здоровье, а также деградацию без активности."
bd create --silent --type task --parent "$HERO" --title "Определить механику старения и ранней смерти" --description "Возраст должен расти со временем, влиять на здоровье и повышать риски при плохом состоянии героя."
bd create --silent --type task --parent "$HERO" --title "Добавить лечение и омоложение" --description "Дорогое лечение должно позволять уменьшить возраст героя на 10 лет."
bd create --silent --type task --parent "$HERO" --title "Определить учет капитала и недвижимости" --description "Капитал считается как деньги плюс стоимость недвижимости, без отдельной сущности богатства."

bd create --silent --type task --parent "$CAREER" --title "Описать модель специальностей и 5 уровней квалификации" --description "Герой может развивать несколько специальностей, каждая имеет 5 уровней развития."
bd create --silent --type task --parent "$CAREER" --title "Спроектировать систему обучения по книгам и материалам" --description "Материалы обучения должны покупатьcя за деньги, идти по таймеру и повышать нужную квалификацию."
bd create --silent --type task --parent "$CAREER" --title "Спроектировать карьерные ступени и переходы между ролями" --description "Нужно описать дерево карьерных переходов, включая старт через QA и возможные ветки в Frontend и Backend."
bd create --silent --type task --parent "$CAREER" --title "Определить рабочие циклы и начисление зарплаты" --description "Постоянная работа должна приносить зарплату за цикл и зависеть от должности."
bd create --silent --type task --parent "$CAREER" --title "Зафиксировать правило неувольняемости" --description "Основную работу потерять нельзя, но можно перейти на другую должность при соблюдении требований."
bd create --silent --type task --parent "$CAREER" --title "Добавить влияние семьи на обучение и карьеру" --description "Семья должна давать бонус к скорости обучения и может влиять на доход и стабильность."

bd create --silent --type task --parent "$ORDERS" --title "Описать 5 уровней ПК и соответствие сложности задач" --description "Для каждого уровня задач должен существовать соответствующий уровень пригодности ПК."
bd create --silent --type task --parent "$ORDERS" --title "Спроектировать модель комплектующих ПК" --description "Нужно определить, какие комплектующие формируют итоговый уровень ПК и открывают доступ к задачам."
bd create --silent --type task --parent "$ORDERS" --title "Описать модель заказа" --description "Заказ должен содержать специальность, уровень сложности, длительность, награду, прирост навыка и шанс провала."
bd create --silent --type task --parent "$ORDERS" --title "Определить шкалу длительности задач 1-5 уровня" --description "Уровень 1 длится 1-2 дня, уровень 5 длится до 30 дней, промежуточные уровни должны быть зафиксированы явно."
bd create --silent --type task --parent "$ORDERS" --title "Составить наборы задач по специальностям и уровням" --description "У каждой специальности должны быть свои типы заказов по всем 5 уровням сложности."
bd create --silent --type task --parent "$ORDERS" --title "Определить механику провала заказа" --description "Нужно описать вероятность провала, последствия и влияние на доход или прогресс."
bd create --silent --type task --parent "$ORDERS" --title "Зафиксировать награды за заказы" --description "Выполнение заказа должно давать деньги и прирост квалификации по соответствующей специальности."

bd create --silent --type task --parent "$SOCIAL" --title "Описать прогулки и приключения" --description "Во время прогулок герой может получать или терять здоровье и деньги, а также сталкиваться со случайными событиями."
bd create --silent --type task --parent "$SOCIAL" --title "Спроектировать механику друзей как источника заказов" --description "Друзья должны появляться на прогулках, выдавать заказы и исчезать после 3 выданных заказов."
bd create --silent --type task --parent "$SOCIAL" --title "Спроектировать отношения, жену и подарки" --description "Жену можно найти на прогулке; подарки должны повышать шанс предложения завести ребенка."
bd create --silent --type task --parent "$SOCIAL" --title "Описать механику детей и роста расходов семьи" --description "Каждый новый член семьи должен увеличивать расходы в разумных пределах и давать бонусы."
bd create --silent --type task --parent "$SOCIAL" --title "Описать механику питомцев" --description "Питомцев может быть несколько; они находятся на прогулках и живут в среднем 2-3 игровых года."
bd create --silent --type task --parent "$SOCIAL" --title "Определить бонусы и скидки от семьи" --description "Нужно зафиксировать бонусы к обучению, возможные бонусы к доходу и систему скидок."

bd create --silent --type task --parent "$UI" --title "Собрать маршрутизацию и каркас приложения" --description "MVP должен иметь отдельные страницы для героя, карьеры, ПК, обучения, хобби и быта."
bd create --silent --type task --parent "$UI" --title "Спроектировать главную страницу героя" --description "Нужен дашборд с параметрами героя, капиталом, семьей, питомцами, рисками и активными таймерами."
bd create --silent --type task --parent "$UI" --title "Спроектировать страницу карьеры" --description "На странице должны отображаться должность, зарплата, карьерные ступени и доступные переходы."
bd create --silent --type task --parent "$UI" --title "Спроектировать страницу ПК и заказов" --description "На странице должны отображаться схематичный компьютер, конфигурация ПК, список заказов и их прогресс."
bd create --silent --type task --parent "$UI" --title "Спроектировать страницу обучения" --description "Нужно показать каталог материалов, стоимость, длительность и активный прогресс обучения."
bd create --silent --type task --parent "$UI" --title "Спроектировать страницу хобби и социальной жизни" --description "Нужно показать прогулки, приключения, друзей, отношения, семью и питомцев."
bd create --silent --type task --parent "$UI" --title "Спроектировать страницу быта и здоровья" --description "Страница должна управлять голодом, спортом, лечением, весом и рисками от старения."

bd create --silent --type task --parent "$CONTENT" --title "Составить стартовый список материалов обучения" --description "Нужно подготовить книги и иные материалы по всем специальностям и уровням."
bd create --silent --type task --parent "$CONTENT" --title "Составить дерево должностей и требований" --description "Нужно определить роли, переходы, требования по навыкам и размер зарплаты."
bd create --silent --type task --parent "$CONTENT" --title "Составить таблицу заказов по специальностям" --description "Нужно подготовить базовый пул заказов по каждой специальности и всем 5 уровням сложности."
bd create --silent --type task --parent "$CONTENT" --title "Составить таблицу случайных событий прогулок" --description "Нужно зафиксировать позитивные и негативные события с влиянием на деньги и здоровье."
bd create --silent --type task --parent "$CONTENT" --title "Составить баланс расходов семьи и содержания питомцев" --description "Нужно определить базовые и растущие затраты по мере расширения семьи."
bd create --silent --type task --parent "$CONTENT" --title "Составить формулы базового баланса игры" --description "Нужно согласовать темп роста денег, навыков, старения, расходов и сложности заказов."

printf "ROOT=%s\nCORE=%s\nHERO=%s\nCAREER=%s\nORDERS=%s\nSOCIAL=%s\nUI=%s\nCONTENT=%s\n" "$ROOT" "$CORE" "$HERO" "$CAREER" "$ORDERS" "$SOCIAL" "$UI" "$CONTENT"
